function f(e){if(!e)return[];let r=new Set,o=[];for(let n of e.split(`;`)){let i=n.trim();if(!i)continue;let t=i.split(`,`);if(t.length!==2)continue;let g=t[0].trim(),c=t[1].trim();if(!g||!c)continue;let u=Number(g),a=Number(c);if(!Number.isFinite(u)||!Number.isFinite(a))continue;let s=`${u},${a}`;r.has(s)||(r.add(s),o.push({gx:u,gy:a}))}return o}function m(e){let r=new Set,o=[];for(let n of e){let g=`${Math.trunc(n.gx)},${Math.trunc(n.gy)}`;r.has(g)||(r.add(g),o.push(g))}return o.join(`;`)}function y(e){if(e.length===0)return{minX:0,minY:0,maxX:0,maxY:0,width:0,height:0};let r=e[0].gx,o=e[0].gx,n=e[0].gy,i=e[0].gy;for(let t of e)t.gx<r&&(r=t.gx),t.gx>o&&(o=t.gx),t.gy<n&&(n=t.gy),t.gy>i&&(i=t.gy);return{minX:r,minY:n,maxX:o,maxY:i,width:o-r+1,height:i-n+1}}function h(e,r){let o=(r%4+4)%4;return o===0?e.map(n=>({gx:n.gx,gy:n.gy})):e.map(n=>{let i,t;switch(o){case 1:i=-n.gy,t=n.gx;break;case 2:i=-n.gx,t=-n.gy;break;default:i=n.gy,t=-n.gx;break}return{gx:i===0?0:i,gy:t===0?0:t}})}function x(e,r){return`${Math.trunc(e)},${Math.trunc(r)}`}function p(e){let r=new Set;for(let o of e)r.add(x(o.gx,o.gy));return r}export{x as a,p as i,h as n,y as o,m as r,f as t};